<script>
import Library from '../../../library/library'
import {
  TABLERONE_URL_MULTIPLE_WAYS_TO_SAVE_TABS,
  TABLERONE_URL_PARTICULAR_RELEASE_NOTE,
  TABLERONE_URL_RELEASE_NOTES
} from '../../../config'

export default {
  name: 'HelpCenter',
  props: {
    // urls
    donationVoteAndSuggestUrl: String,
    privacyPolicyUrl: String,
    termsOfServiceUrl: String,
    setAsHomePageUrl: String
  },
  data: () => {
    return {
      copied: false, // was copy to clipboard clicked

      releaseNotesUrl: '',

      urlLearnMoreAboutMultipleWays: '',

      version: 'v1.0', // version from manifest
      TABLERONE_URL_PARTICULAR_RELEASE_NOTE: ''
    }
  },
  mounted() {
    this.releaseNotesUrl = TABLERONE_URL_RELEASE_NOTES
    this.urlLearnMoreAboutMultipleWays =
      TABLERONE_URL_MULTIPLE_WAYS_TO_SAVE_TABS
    this.version = '' + chrome.runtime.getManifest().version
    this.TABLERONE_URL_PARTICULAR_RELEASE_NOTE =
      TABLERONE_URL_PARTICULAR_RELEASE_NOTE +
      this.version.replaceAll('.', '-').replace('v', 'v-') +
      '/'
  },
  methods: {
    discardChanges() {
      this.$emit('closeHelpcenter')
    },
    copyToClipboard() {
      Library.copyToClipboard(
        '<a href="https://tabler.one/" rel="dofollow">Tablerone tab session manager</a>'
      )

      // change text
      this.copied = true
      const self = this
      setTimeout(function () {
        self.copied = false
      }, 3000)

      this.sendMessage({
        command: 'tracking.add.event',
        eventName: 'helpcenterCopyToClipboardClick',
        eventProps: {}
      })
    },
    sendMessage(message, callback) {
      // for sending message to background.js
      // message.sourceWindowId = this.thisWindowId //always add windowId for identification (this is probably not used anywhere - test)
      message.messageSenderSource = 'cluster'

      console.log('senMessage called from cluster', message)

      try {
        chrome.runtime.sendMessage(
          null,
          message,
          callback !== undefined && callback !== null
            ? callback
            : function (x) {
                console.log(
                  'sendMessage called, message and response are: ',
                  message,
                  x
                )
                void chrome.runtime.lastError
              }
        ) // for external messages params look like (extId, message, callback)
      } catch (e) {
        console.log('wtf?', e.toString())
      }
    },
    triggerMailto() {
      this.sendMessage({
        command: 'tracking.add.event',
        eventName: 'reportABug',
        eventProps: {
          source: 'helpcenter'
        }
      })

      // window.open(this.mailtoString());
      const newlink = document.createElement('a')
      newlink.setAttribute('href', this.mailtoString())
      newlink.setAttribute('target', '_new') // if you have gmail as default, this should be done like this
      newlink.click()
      try {
        document.removeChild(newlink)
      } catch (e) {}

      return true
    },

    mailtoString() {
      const subject = 'Reporting a bug'
      const nAgt = navigator.userAgent
      let browserName = navigator.appName
      let fullVersion = '' + parseFloat(navigator.appVersion)
      let majorVersion = parseInt(navigator.appVersion, 10)
      let nameOffset, verOffset, ix

      // In Opera, the true version is after "Opera" or after "Version"
      if ((verOffset = nAgt.indexOf('Opera')) != -1) {
        browserName = 'Opera'
        fullVersion = nAgt.substring(verOffset + 6)
        if ((verOffset = nAgt.indexOf('Version')) != -1) {
          fullVersion = nAgt.substring(verOffset + 8)
        }
      }
      // In MSIE, the true version is after "MSIE" in userAgent
      else if ((verOffset = nAgt.indexOf('MSIE')) != -1) {
        browserName = 'Microsoft Internet Explorer'
        fullVersion = nAgt.substring(verOffset + 5)
      }
      // In Chrome, the true version is after "Chrome"
      else if ((verOffset = nAgt.indexOf('Chrome')) != -1) {
        browserName = 'Chrome'
        fullVersion = nAgt.substring(verOffset + 7)
      }
      // In Firefox, the true version is after "Firefox"
      else if ((verOffset = nAgt.indexOf('Firefox')) != -1) {
        browserName = 'Firefox'
        fullVersion = nAgt.substring(verOffset + 8)
      }
      // In most other browsers, "name/version" is at the end of userAgent
      else if (
        (nameOffset = nAgt.lastIndexOf(' ') + 1) <
        (verOffset = nAgt.lastIndexOf('/'))
      ) {
        browserName = nAgt.substring(nameOffset, verOffset)
        fullVersion = nAgt.substring(verOffset + 1)
        if (browserName.toLowerCase() == browserName.toUpperCase()) {
          browserName = navigator.appName
        }
      }
      // trim the fullVersion string at semicolon/space if present
      if ((ix = fullVersion.indexOf(';')) != -1) {
        fullVersion = fullVersion.substring(0, ix)
      }
      if ((ix = fullVersion.indexOf(' ')) != -1) {
        fullVersion = fullVersion.substring(0, ix)
      }

      majorVersion = parseInt('' + fullVersion, 10)
      if (isNaN(majorVersion)) {
        fullVersion = '' + parseFloat(navigator.appVersion)
        majorVersion = parseInt(navigator.appVersion, 10)
      }

      let OSName = 'Unknown OS'
      if (navigator.appVersion.indexOf('Win') != -1) OSName = 'Windows'
      if (navigator.appVersion.indexOf('Mac') != -1) OSName = 'MacOS'
      if (navigator.appVersion.indexOf('X11') != -1) OSName = 'UNIX'
      if (navigator.appVersion.indexOf('Linux') != -1) OSName = 'Linux'

      const body =
        'Details (please do not delete and write below)\n\n' +
        'Browser name: ' +
        browserName +
        '\n' +
        'Browser full: ' +
        navigator.userAgent +
        '\n' +
        'Full version: ' +
        fullVersion +
        '\n' +
        'Major version: ' +
        majorVersion +
        '\n' +
        'OS: ' +
        OSName +
        '\n' +
        'Width: ' +
        window.screen.availWidth +
        '\n' +
        'Height: ' +
        window.screen.availHeight +
        '\n' +
        '\n--------------\n\n\n'

      const mailtoString =
        'mailto:' +
        'feedback@tabler.one' +
        '?subject=' +
        encodeURIComponent(subject) +
        '&body=' +
        encodeURIComponent(body)
      return mailtoString
    },
    seeWalktroughVideo() {
      this.sendMessage({
        command: 'tracking.add.event',
        eventName: 'helpcenterSeeWalktroughVideo',
        eventProps: {}
      })
    },
    faq(order) {
      this.sendMessage({
        command: 'tracking.add.event',
        eventName: 'helpcenterFaq',
        eventProps: {
          order
        }
      })
    },
    getInvolved(type) {
      this.sendMessage({
        command: 'tracking.add.event',
        eventName: 'helpcenterFaq',
        eventProps: {
          type
        }
      })
    },
    writeAReview() {
      this.sendMessage({
        command: 'tracking.add.event',
        eventName: 'helpcenterWriteAReview  ',
        eventProps: {}
      })
    }
  },
  computed: {},
  watch: {}
}
</script>

